CREATE DATABASE mvcclab;
\c mvcclab
CREATE TABLE accounts (
    id      integer PRIMARY KEY,
    owner   text    NOT NULL,
    balance numeric NOT NULL
);
INSERT INTO accounts VALUES
    (1, 'Asha',  5000),
    (2, 'Ravi',  3000),
    (3, 'Meera', 7000);

BEGIN;
UPDATE accounts SET balance = balance - 1000 WHERE id = 1;
SELECT pg_current_xact_id();
SELECT xmin, xmax, ctid, * FROM accounts ORDER BY id;

CREATE EXTENSION pageinspect;
SELECT lp, lp_flags, t_xmin, t_xmax, t_ctid
  FROM heap_page_items(get_raw_page('accounts', 0));

BEGIN;
DELETE FROM accounts WHERE id = 2;
SELECT pg_current_xact_id();
ROLLBACK;
SELECT xmin, xmax, ctid, * FROM accounts ORDER BY id;

-- Terminal 2
BEGIN;
SELECT balance FROM accounts WHERE id = 3;   -- returns 7000

-- Terminal 1 (autocommit, commits at once)
UPDATE accounts SET balance = balance + 500 WHERE id = 3;

-- Terminal 2, same transaction
SELECT balance FROM accounts WHERE id = 3;
COMMIT;

-- Terminal 2
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE id = 3;   -- returns 7500

-- Terminal 1
UPDATE accounts SET balance = balance + 500 WHERE id = 3;

-- Terminal 2, same transaction
SELECT balance FROM accounts WHERE id = 3;
UPDATE accounts SET balance = balance - 100 WHERE id = 3;
ROLLBACK;

-- Terminal 1
VACUUM accounts;

-- Terminal 2: open a transaction and leave it open
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance) FROM accounts;

-- Terminal 1
UPDATE accounts SET balance = balance + 100;
SELECT n_live_tup, n_dead_tup, n_tup_upd, n_tup_hot_upd
  FROM pg_stat_user_tables
 WHERE relname = 'accounts';

SELECT lp, lp_flags, lp_off, t_xmin, t_xmax, t_ctid
  FROM heap_page_items(get_raw_page('accounts', 0));
SELECT xmin, xmax, ctid, * FROM accounts ORDER BY id;
